#!/usr/bin/env python3
"""
yj - Convert between YAML, TOML, JSON, and HCL.
Preserves map order.
"""

import sys
import json
import math
import re
import os
import io
from collections import OrderedDict

# =============================================================================
# YAML Parser and Serializer
# =============================================================================

class YAMLParser:
    """A YAML parser that handles common YAML 1.2 constructs."""

    def __init__(self, text):
        self.text = text
        self.lines = text.split('\n')
        self.pos = 0  # current line index
        self.anchors = {}

    def parse(self):
        """Parse and return the root value."""
        return self._parse_document()

    def _parse_document(self):
        """Parse a YAML document."""
        # Skip document start markers
        while self.pos < len(self.lines):
            line = self.lines[self.pos]
            stripped = line.strip()
            if stripped == '---' or stripped == '':
                self.pos += 1
                continue
            break

        if self.pos >= len(self.lines):
            return None

        return self._parse_value(0)

    def _get_indent(self, line):
        """Get the indentation level of a line."""
        return len(line) - len(line.lstrip())

    def _is_comment_or_empty(self, line):
        """Check if a line is empty or a comment."""
        stripped = line.strip()
        return stripped == '' or stripped.startswith('#')

    def _parse_value(self, min_indent):
        """Parse a value starting at current position."""
        # Skip empty lines and comments
        while self.pos < len(self.lines):
            line = self.lines[self.pos]
            if not self._is_comment_or_empty(line):
                break
            self.pos += 1

        if self.pos >= len(self.lines):
            return None

        line = self.lines[self.pos]
        indent = self._get_indent(line)

        if indent < min_indent:
            return None

        stripped = line.strip()

        # Handle document start/end markers
        if stripped == '---' or stripped == '...':
            self.pos += 1
            return self._parse_value(min_indent)

        # Check for block sequence (starts with -)
        if stripped.startswith('- ') or stripped == '-':
            return self._parse_block_sequence(indent)

        # Check for block mapping (key: value)
        if self._looks_like_mapping_key(stripped, indent):
            return self._parse_block_mapping(indent)

        # Otherwise it's a scalar
        return self._parse_scalar_value(stripped, min_indent)

    def _looks_like_mapping_key(self, stripped, indent):
        """Check if current line looks like a mapping key."""
        if not stripped:
            return False

        # Check for ? explicit mapping key
        if stripped.startswith('? '):
            return True

        # Try to find key: pattern
        # Handle quoted keys
        if stripped.startswith('"'):
            # Find closing quote
            end = stripped.find('"', 1)
            if end > 0 and end + 1 < len(stripped) and stripped[end+1] == ':':
                return True
        elif stripped.startswith("'"):
            end = stripped.find("'", 1)
            if end > 0 and end + 1 < len(stripped) and stripped[end+1] == ':':
                return True
        else:
            # Unquoted key - find colon
            for i, c in enumerate(stripped):
                if c == ':' and (i+1 >= len(stripped) or stripped[i+1] in ' \t\n\r'):
                    return True
                if c in '#\n':
                    break

        return False

    def _parse_block_sequence(self, indent):
        """Parse a block sequence (list)."""
        result = []

        while self.pos < len(self.lines):
            # Skip empty/comment lines
            while self.pos < len(self.lines) and self._is_comment_or_empty(self.lines[self.pos]):
                self.pos += 1

            if self.pos >= len(self.lines):
                break

            line = self.lines[self.pos]
            cur_indent = self._get_indent(line)

            if cur_indent < indent:
                break

            if cur_indent > indent:
                # Shouldn't happen at sequence level, but handle it
                break

            stripped = line.strip()

            if not stripped.startswith('-'):
                break

            self.pos += 1

            # Get the value after -
            after_dash = stripped[1:]

            if after_dash == '' or after_dash.startswith(' '):
                after_dash = after_dash[1:] if after_dash.startswith(' ') else ''

                if after_dash == '' or after_dash.startswith('#'):
                    # Value is on next line(s)
                    # Check next line
                    while self.pos < len(self.lines) and self._is_comment_or_empty(self.lines[self.pos]):
                        self.pos += 1

                    if self.pos < len(self.lines):
                        next_line = self.lines[self.pos]
                        next_indent = self._get_indent(next_line)

                        if next_indent > indent:
                            value = self._parse_value(next_indent)
                        else:
                            value = None
                    else:
                        value = None
                else:
                    # Inline value after - 
                    # Check if it's a mapping or sequence key
                    if self._looks_like_mapping_key(after_dash, indent + 2):
                        # Parse as inline block mapping
                        value = self._parse_inline_mapping_from_dash(indent + 2, after_dash, line)
                    elif after_dash.startswith('- ') or after_dash == '-':
                        # Nested sequence - need to handle differently
                        saved_pos = self.pos
                        self.pos -= 1
                        sub_line = ' ' * (indent + 2) + after_dash
                        # Save and replace
                        orig_line = self.lines[self.pos]
                        self.lines[self.pos] = sub_line
                        value = self._parse_block_sequence(indent + 2)
                        self.lines[self.pos] = orig_line
                    else:
                        # Parse scalar value
                        value = self._parse_scalar_inline(after_dash)
                        if value is None:
                            value = self._convert_scalar(after_dash)
            else:
                # No space after dash - just '-'
                value = None

            result.append(value)

        return result

    def _parse_inline_mapping_from_dash(self, min_indent, first_line_rest, full_line):
        """Parse a mapping that starts inline after a list dash."""
        result = OrderedDict()

        # First parse the inline key: value on the same line
        first_items = self._parse_single_mapping_line(first_line_rest)
        for k, v in first_items.items():
            result[k] = v

        # Then continue with more items at the same indent level
        while self.pos < len(self.lines):
            while self.pos < len(self.lines) and self._is_comment_or_empty(self.lines[self.pos]):
                self.pos += 1

            if self.pos >= len(self.lines):
                break

            line = self.lines[self.pos]
            cur_indent = self._get_indent(line)

            if cur_indent < min_indent:
                break

            stripped = line.strip()

            if stripped.startswith('- ') or stripped == '-':
                break

            if not self._looks_like_mapping_key(stripped, cur_indent):
                break

            self.pos += 1
            items = self._parse_key_value_line(stripped, cur_indent)
            for k, v in items.items():
                result[k] = v

        return result

    def _parse_block_mapping(self, indent):
        """Parse a block mapping (dict)."""
        result = OrderedDict()

        while self.pos < len(self.lines):
            # Skip empty/comment lines
            while self.pos < len(self.lines) and self._is_comment_or_empty(self.lines[self.pos]):
                self.pos += 1

            if self.pos >= len(self.lines):
                break

            line = self.lines[self.pos]
            cur_indent = self._get_indent(line)

            if cur_indent < indent:
                break

            if cur_indent > indent:
                break

            stripped = line.strip()

            # If we hit a list item, stop parsing mapping
            if stripped.startswith('- ') or stripped == '-':
                break

            if not self._looks_like_mapping_key(stripped, cur_indent):
                break

            self.pos += 1

            # Parse key and value
            kv = self._parse_key_value_line(stripped, cur_indent)
            for k, v in kv.items():
                if k == '<<':
                    # Merge key
                    if isinstance(v, dict):
                        for mk, mv in v.items():
                            if mk not in result:
                                result[mk] = mv
                    elif isinstance(v, list):
                        for item in v:
                            if isinstance(item, dict):
                                for mk, mv in item.items():
                                    if mk not in result:
                                        result[mk] = mv
                else:
                    result[k] = v

        return result

    def _parse_key_value_line(self, stripped, indent):
        """Parse a single key: value line and return as dict."""
        result = OrderedDict()

        key, rest = self._split_key_colon(stripped)
        if key is None:
            return result

        # Handle anchors in key (&anchor)
        anchor = None
        if rest is not None and rest.startswith('&'):
            anchor_match = re.match(r'^&(\S+)\s*(.*)', rest)
            if anchor_match:
                anchor = anchor_match.group(1)
                rest = anchor_match.group(2)

        if rest is None or rest == '' or rest.startswith('#'):
            # Value is on next line(s)
            while self.pos < len(self.lines) and self._is_comment_or_empty(self.lines[self.pos]):
                self.pos += 1

            if self.pos < len(self.lines):
                next_line = self.lines[self.pos]
                next_indent = self._get_indent(next_line)

                if next_indent > indent:
                    value = self._parse_value(next_indent)
                else:
                    value = None
            else:
                value = None
        else:
            # Inline value
            value = self._parse_scalar_inline(rest)
            if value is NOTPARSED:
                value = self._convert_scalar(rest)

        if anchor:
            self.anchors[anchor] = value

        result[key] = value
        return result

    def _parse_single_mapping_line(self, text):
        """Parse a single key: value and return as OrderedDict."""
        result = OrderedDict()
        key, rest = self._split_key_colon(text)
        if key is None:
            return result

        if rest is None or rest == '' or rest.startswith('#'):
            value = None
        else:
            value = self._parse_scalar_inline(rest)
            if value is NOTPARSED:
                value = self._convert_scalar(rest)

        result[key] = value
        return result

    def _split_key_colon(self, text):
        """Split 'key: value' into (key, rest). Returns (None, None) on failure."""
        if not text:
            return None, None

        # Handle merge key
        if text == '<<:' or text.startswith('<<: ') or text.startswith('<<:'):
            rest = text[3:].lstrip()
            if not rest:
                return '<<', None
            return '<<', rest

        # Handle explicit key marker
        if text.startswith('? '):
            # Complex key
            return text[2:].strip(), None

        # Quoted key
        if text.startswith('"'):
            end = text.find('"', 1)
            while end > 0 and text[end-1] == '\\':
                end = text.find('"', end+1)
            if end < 0:
                return None, None
            key = self._parse_quoted_string(text[1:end])
            rest_part = text[end+1:].lstrip()
            if rest_part.startswith(':'):
                rest = rest_part[1:].lstrip() if len(rest_part) > 1 else ''
                return key, rest
            return None, None

        if text.startswith("'"):
            end = text.find("'", 1)
            if end < 0:
                return None, None
            key = text[1:end].replace("''", "'")
            rest_part = text[end+1:].lstrip()
            if rest_part.startswith(':'):
                rest = rest_part[1:].lstrip() if len(rest_part) > 1 else ''
                return key, rest
            return None, None

        # Unquoted key - find colon not inside quotes
        for i, c in enumerate(text):
            if c == ':':
                if i+1 >= len(text) or text[i+1] in ' \t':
                    key = text[:i].rstrip()
                    rest = text[i+2:].lstrip() if i+2 <= len(text) else ''
                    return key, rest
                elif i+1 == len(text):
                    key = text[:i].rstrip()
                    return key, ''

        return None, None

    def _parse_scalar_inline(self, text):
        """Parse an inline scalar value. Returns NOTPARSED sentinel if not a scalar."""
        text = text.strip()

        if not text or text.startswith('#'):
            return None

        # Flow sequence
        if text.startswith('['):
            return self._parse_flow_sequence(text)

        # Flow mapping
        if text.startswith('{'):
            return self._parse_flow_mapping(text)

        # Anchor reference
        if text.startswith('*'):
            anchor_name = text[1:].strip()
            return self.anchors.get(anchor_name)

        # Anchor definition
        if text.startswith('&'):
            m = re.match(r'^&(\S+)\s*(.*)', text)
            if m:
                anchor_name = m.group(1)
                rest = m.group(2).strip()
                if rest:
                    value = self._parse_scalar_inline(rest)
                    if value is NOTPARSED:
                        value = self._convert_scalar(rest)
                else:
                    value = None
                self.anchors[anchor_name] = value
                return value

        # Block scalar indicators
        if text.startswith('|') or text.startswith('>'):
            return self._parse_block_scalar(text)

        # Tag
        if text.startswith('!!'):
            m = re.match(r'^!!(\S+)\s*(.*)', text)
            if m:
                tag = m.group(1)
                rest = m.group(2).strip()
                return self._parse_tagged_value(tag, rest)

        if text.startswith('!'):
            m = re.match(r'^!(\S*)\s*(.*)', text)
            if m:
                tag = m.group(1)
                rest = m.group(2).strip()
                if tag:
                    return self._parse_tagged_value(tag, rest)

        return NOTPARSED

    def _parse_block_scalar(self, indicator):
        """Parse a block scalar (| or >)."""
        # Parse the block scalar indicator and optional modifiers
        style = indicator[0]  # | or >
        rest = indicator[1:].strip()

        # Parse chomp and indent indicators
        chomp = 'clip'  # default
        explicit_indent = None

        for c in rest:
            if c == '-':
                chomp = 'strip'
            elif c == '+':
                chomp = 'keep'
            elif c.isdigit():
                explicit_indent = int(c)
            else:
                break

        # Determine the indentation from the first content line
        base_indent = None
        lines = []

        while self.pos < len(self.lines):
            line = self.lines[self.pos]

            if not line.strip() and not lines:
                self.pos += 1
                lines.append('')
                continue

            cur_indent = self._get_indent(line)

            if not line.strip():
                # Empty line
                self.pos += 1
                lines.append('')
                continue

            if base_indent is None:
                if explicit_indent is not None:
                    # Find parent indent and add explicit_indent
                    base_indent = cur_indent
                else:
                    base_indent = cur_indent

            if cur_indent < base_indent:
                break

            self.pos += 1
            lines.append(line[base_indent:])

        # Remove leading empty lines
        while lines and lines[0] == '':
            lines.pop(0)

        if style == '|':
            # Literal: preserve newlines
            content = '\n'.join(lines)
        else:
            # Folded: fold newlines to spaces
            # Complex folding logic
            content = self._fold_block_scalar(lines)

        # Apply chomp
        if chomp == 'strip':
            content = content.rstrip('\n')
        elif chomp == 'clip':
            content = content.rstrip('\n') + '\n' if content else content
        # keep: leave trailing newlines

        return content

    def _fold_block_scalar(self, lines):
        """Apply folded block scalar processing."""
        result = []
        i = 0
        while i < len(lines):
            line = lines[i]
            if line == '':
                result.append('\n')
                i += 1
            elif i + 1 < len(lines) and lines[i+1] == '':
                result.append(line)
                result.append('\n')
                i += 1
            elif i + 1 < len(lines) and not lines[i+1].startswith(' '):
                result.append(line)
                result.append(' ')
                i += 1
            else:
                result.append(line)
                if i + 1 < len(lines):
                    result.append('\n')
                i += 1

        # Fix multiple newlines
        content = ''.join(result)
        return content + '\n'

    def _parse_tagged_value(self, tag, value):
        """Parse a tagged YAML value."""
        if tag == 'binary':
            import base64
            data = base64.b64decode(value.replace(' ', '').replace('\n', ''))
            return data.decode('utf-8', errors='replace')
        elif tag in ('str', 'string'):
            return str(value)
        elif tag == 'int':
            return int(value, 0) if value else 0
        elif tag == 'float':
            return float(value) if value else 0.0
        elif tag == 'bool':
            return value.lower() in ('true', 'yes', 'on', '1')
        elif tag == 'null':
            return None
        elif tag == 'seq':
            return self._parse_flow_sequence(value) if value.startswith('[') else []
        elif tag == 'map':
            return self._parse_flow_mapping(value) if value.startswith('{') else OrderedDict()
        return self._convert_scalar(value)

    def _parse_flow_sequence(self, text):
        """Parse a flow sequence like [1, 2, 3]."""
        text = text.strip()
        if not text.startswith('['):
            return []

        result = []
        i = 1  # skip [

        while i < len(text):
            # Skip whitespace
            while i < len(text) and text[i] in ' \t\n':
                i += 1

            if i >= len(text):
                break

            if text[i] == ']':
                break

            # Parse value
            value, i = self._parse_flow_value(text, i)
            result.append(value)

            # Skip whitespace and comma
            while i < len(text) and text[i] in ' \t\n':
                i += 1

            if i < len(text) and text[i] == ',':
                i += 1

        return result

    def _parse_flow_mapping(self, text):
        """Parse a flow mapping like {a: 1, b: 2}."""
        text = text.strip()
        if not text.startswith('{'):
            return OrderedDict()

        result = OrderedDict()
        i = 1  # skip {

        while i < len(text):
            # Skip whitespace
            while i < len(text) and text[i] in ' \t\n':
                i += 1

            if i >= len(text):
                break

            if text[i] == '}':
                break

            # Parse key
            key, i = self._parse_flow_value(text, i)

            # Skip whitespace and colon
            while i < len(text) and text[i] in ' \t\n':
                i += 1

            if i < len(text) and text[i] == ':':
                i += 1
            else:
                # No colon found, skip
                continue

            # Skip whitespace
            while i < len(text) and text[i] in ' \t\n':
                i += 1

            # Parse value
            if i < len(text) and text[i] not in ',}':
                value, i = self._parse_flow_value(text, i)
            else:
                value = None

            result[str(key) if key is not None else ''] = value

            # Skip whitespace and comma
            while i < len(text) and text[i] in ' \t\n':
                i += 1

            if i < len(text) and text[i] == ',':
                i += 1

        return result

    def _parse_flow_value(self, text, i):
        """Parse a single flow value starting at position i. Returns (value, new_i)."""
        # Skip whitespace
        while i < len(text) and text[i] in ' \t\n':
            i += 1

        if i >= len(text):
            return None, i

        c = text[i]

        if c == '"':
            # Double-quoted string
            j = i + 1
            s = ''
            while j < len(text) and text[j] != '"':
                if text[j] == '\\':
                    j += 1
                    if j < len(text):
                        s += self._unescape_char(text[j])
                        j += 1
                else:
                    s += text[j]
                    j += 1
            return s, j + 1

        elif c == "'":
            # Single-quoted string
            j = i + 1
            s = ''
            while j < len(text):
                if text[j] == "'" and j+1 < len(text) and text[j+1] == "'":
                    s += "'"
                    j += 2
                elif text[j] == "'":
                    break
                else:
                    s += text[j]
                    j += 1
            return s, j + 1

        elif c == '[':
            # Nested sequence
            end = self._find_closing(text, i, '[', ']')
            return self._parse_flow_sequence(text[i:end+1]), end + 1

        elif c == '{':
            # Nested mapping
            end = self._find_closing(text, i, '{', '}')
            return self._parse_flow_mapping(text[i:end+1]), end + 1

        else:
            # Scalar
            j = i
            while j < len(text) and text[j] not in ',}]\n':
                j += 1
