        result[key] = value
        return result

    def _split_key_colon(self, text):
        """Split 'key: value' into (key, rest). Returns (None, None) on failure."""
        if not text:
            return None, None

        # Handle merge key
        if text == '<<:' or text.startswith('<<: ') or text.startswith('<<:'):
            rest = text[3:].lstrip()
            if not rest:
                return '<<', None
            return '<<', rest

        # Handle explicit key marker
        if text.startswith('? '):
            # Complex key
            return text[2:].strip(), None

        # Quoted key
        if text.startswith('"'):
            end = text.find('"', 1)
            while end > 0 and text[end-1] == '\\':
                end = text.find('"', end+1)
            if end < 0:
                return None, None
            key = self._parse_quoted_string(text[1:end])
            rest_part = text[end+1:].lstrip()
            if rest_part.startswith(':'):
                rest = rest_part[1:].lstrip() if len(rest_part) > 1 else ''
                return key, rest
            return None, None

        if text.startswith("'"):
            end = text.find("'", 1)
            if end < 0:
                return None, None
            key = text[1:end].replace("''", "'")
            rest_part = text[end+1:].lstrip()
            if rest_part.startswith(':'):
                rest = rest_part[1:].lstrip() if len(rest_part) > 1 else ''
                return key, rest
            return None, None

        # Unquoted key - find colon not inside quotes
        for i, c in enumerate(text):
            if c == ':':
                if i+1 >= len(text) or text[i+1] in ' \t':
                    key = text[:i].rstrip()
                    rest = text[i+2:].lstrip() if i+2 <= len(text) else ''
                    return key, rest
                elif i+1 == len(text):
                    key = text[:i].rstrip()
                    return key, ''

        return None, None

    def _parse_scalar_inline(self, text):
        """Parse an inline scalar value. Returns NOTPARSED sentinel if not a scalar."""
        text = text.strip()

        if not text or text.startswith('#'):
            return None

        # Flow sequence
        if text.startswith('['):
            return self._parse_flow_sequence(text)

        # Flow mapping
        if text.startswith('{'):
            return self._parse_flow_mapping(text)

        # Anchor reference
        if text.startswith('*'):
            anchor_name = text[1:].strip()
            return self.anchors.get(anchor_name)

        # Anchor definition
        if text.startswith('&'):
            m = re.match(r'^&(\S+)\s*(.*)', text)
            if m:
                anchor_name = m.group(1)
                rest = m.group(2).strip()
                if rest:
                    value = self._parse_scalar_inline(rest)
                    if value is NOTPARSED:
                        value = self._convert_scalar(rest)
                else:
                    value = None
                self.anchors[anchor_name] = value
                return value

        # Block scalar indicators
        if text.startswith('|') or text.startswith('>'):
            return self._parse_block_scalar(text)

        # Tag
        if text.startswith('!!'):
            m = re.match(r'^!!(\S+)\s*(.*)', text)
            if m:
                tag = m.group(1)
                rest = m.group(2).strip()
                return self._parse_tagged_value(tag, rest)

        if text.startswith('!'):
            m = re.match(r'^!(\S*)\s*(.*)', text)
            if m:
                tag = m.group(1)
                rest = m.group(2).strip()
                if tag:
                    return self._parse_tagged_value(tag, rest)

        return NOTPARSED

    def _parse_block_scalar(self, indicator):
        """Parse a block scalar (| or >)."""
        # Parse the block scalar indicator and optional modifiers
        style = indicator[0]  # | or >
        rest = indicator[1:].strip()

        # Parse chomp and indent indicators
        chomp = 'clip'  # default
        explicit_indent = None

        for c in rest:
            if c == '-':
                chomp = 'strip'
            elif c == '+':
                chomp = 'keep'
            elif c.isdigit():
                explicit_indent = int(c)
            else:
                break

        # Determine the indentation from the first content line
        base_indent = None
        lines = []

        while self.pos < len(self.lines):
            line = self.lines[self.pos]

            if not line.strip() and not lines:
                self.pos += 1
                lines.append('')
                continue

            cur_indent = self._get_indent(line)

            if not line.strip():
                # Empty line
                self.pos += 1
                lines.append('')
                continue

            if base_indent is None:
                if explicit_indent is not None:
                    # Find parent indent and add explicit_indent
                    base_indent = cur_indent
                else:
                    base_indent = cur_indent

            if cur_indent < base_indent:
                break

            self.pos += 1
            lines.append(line[base_indent:])

        # Remove leading empty lines
        while lines and lines[0] == '':
            lines.pop(0)

        if style == '|':
            # Literal: preserve newlines
            content = '\n'.join(lines)
        else:
            # Folded: fold newlines to spaces
            # Complex folding logic
            content = self._fold_block_scalar(lines)

        # Apply chomp
        if chomp == 'strip':
            content = content.rstrip('\n')
        elif chomp == 'clip':
            content = content.rstrip('\n') + '\n' if content else content
        # keep: leave trailing newlines

        return content

    def _fold_block_scalar(self, lines):
        """Apply folded block scalar processing."""
        result = []
        i = 0
        while i < len(lines):
            line = lines[i]
            if line == '':
                result.append('\n')
                i += 1
            elif i + 1 < len(lines) and lines[i+1] == '':
                result.append(line)
                result.append('\n')
                i += 1
            elif i + 1 < len(lines) and not lines[i+1].startswith(' '):
                result.append(line)
                result.append(' ')
                i += 1
            else:
                result.append(line)
                if i + 1 < len(lines):
                    result.append('\n')
                i += 1

        # Fix multiple newlines
        content = ''.join(result)
        return content + '\n'

    def _parse_tagged_value(self, tag, value):
        """Parse a tagged YAML value."""
        if tag == 'binary':
            import base64
            data = base64.b64decode(value.replace(' ', '').replace('\n', ''))
            return data.decode('utf-8', errors='replace')
        elif tag in ('str', 'string'):
            return str(value)
        elif tag == 'int':
            return int(value, 0) if value else 0
        elif tag == 'float':
            return float(value) if value else 0.0
        elif tag == 'bool':
            return value.lower() in ('true', 'yes', 'on', '1')
        elif tag == 'null':
            return None
        elif tag == 'seq':
            return self._parse_flow_sequence(value) if value.startswith('[') else []
        elif tag == 'map':
            return self._parse_flow_mapping(value) if value.startswith('{') else OrderedDict()
        return self._convert_scalar(value)

    def _parse_flow_sequence(self, text):
        """Parse a flow sequence like [1, 2, 3]."""
        text = text.strip()
        if not text.startswith('['):
            return []

        result = []
        i = 1  # skip [

        while i < len(text):
            # Skip whitespace
            while i < len(text) and text[i] in ' \t\n':
                i += 1

            if i >= len(text):
                break

            if text[i] == ']':
                break

            # Parse value
            value, i = self._parse_flow_value(text, i)
            result.append(value)

            # Skip whitespace and comma
            while i < len(text) and text[i] in ' \t\n':
                i += 1

            if i < len(text) and text[i] == ',':
                i += 1

        return result

    def _parse_flow_mapping(self, text):
        """Parse a flow mapping like {a: 1, b: 2}."""
        text = text.strip()
        if not text.startswith('{'):
            return OrderedDict()

        result = OrderedDict()
        i = 1  # skip {

        while i < len(text):
            # Skip whitespace
            while i < len(text) and text[i] in ' \t\n':
                i += 1

            if i >= len(text):
                break

            if text[i] == '}':
                break

            # Parse key
            key, i = self._parse_flow_value(text, i)

            # Skip whitespace and colon
            while i < len(text) and text[i] in ' \t\n':
                i += 1

            if i < len(text) and text[i] == ':':
                i += 1
            else:
                # No colon found, skip
                continue

            # Skip whitespace
            while i < len(text) and text[i] in ' \t\n':
                i += 1

            # Parse value
            if i < len(text) and text[i] not in ',}':
                value, i = self._parse_flow_value(text, i)
            else:
                value = None

            result[str(key) if key is not None else ''] = value

            # Skip whitespace and comma
            while i < len(text) and text[i] in ' \t\n':
                i += 1

            if i < len(text) and text[i] == ',':
                i += 1

        return result

    def _parse_flow_value(self, text, i):
        """Parse a single flow value starting at position i. Returns (value, new_i)."""
        # Skip whitespace
        while i < len(text) and text[i] in ' \t\n':
            i += 1

        if i >= len(text):
            return None, i

        c = text[i]

        if c == '"':
            # Double-quoted string
            j = i + 1
            s = ''
            while j < len(text) and text[j] != '"':
                if text[j] == '\\':
                    j += 1
                    if j < len(text):
                        s += self._unescape_char(text[j])
                        j += 1
                else:
                    s += text[j]
                    j += 1
            return s, j + 1

        elif c == "'":
            # Single-quoted string
            j = i + 1
            s = ''
            while j < len(text):
                if text[j] == "'" and j+1 < len(text) and text[j+1] == "'":
                    s += "'"
                    j += 2
                elif text[j] == "'":
                    break
                else:
                    s += text[j]
                    j += 1
            return s, j + 1

        elif c == '[':
            # Nested sequence
            end = self._find_closing(text, i, '[', ']')
            return self._parse_flow_sequence(text[i:end+1]), end + 1

        elif c == '{':
            # Nested mapping
            end = self._find_closing(text, i, '{', '}')
            return self._parse_flow_mapping(text[i:end+1]), end + 1

        else:
            # Scalar
            j = i
            while j < len(text) and text[j] not in ',}]\n':
                j += 1
            scalar = text[i:j].strip()
            return self._convert_scalar(scalar), j

    def _find_closing(self, text, start, open_c, close_c):
        """Find the position of the matching closing bracket."""
        depth = 0
        i = start
        in_str = None
        while i < len(text):
            c = text[i]
            if in_str:
                if c == '\\' and in_str == '"':
                    i += 2
                    continue
                if c == in_str:
                    in_str = None
            elif c in '"\'':
                in_str = c
            elif c == open_c:
                depth += 1
            elif c == close_c:
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        return i - 1

    def _parse_quoted_string(self, s):
        """Parse a double-quoted string content (without outer quotes)."""
        result = ''
        i = 0
        while i < len(s):
            if s[i] == '\\':
                i += 1
                if i < len(s):
                    result += self._unescape_char(s[i])
                    i += 1
            else:
                result += s[i]
                i += 1
        return result

    def _unescape_char(self, c):
        """Unescape a single character after backslash."""
        mapping = {
            'n': '\n', 't': '\t', 'r': '\r', 'b': '\b', 'f': '\f',
            '"': '"', "'": "'", '\\': '\\', '/': '/', 'a': '\a',
            'v': '\v', 'e': '\x1b', '0': '\x00', ' ': ' ', '_': '\xa0',
            'N': '\x85', 'L': '\u2028', 'P': '\u2029',
        }
        return mapping.get(c, c)

    def _convert_scalar(self, text):
        """Convert a YAML scalar string to a Python value."""
        if text is None:
            return None

        text = text.strip()

        # Remove inline comments
        # But be careful not to strip from inside strings

        # Check for double-quoted string
        if text.startswith('"') and text.endswith('"') and len(text) >= 2:
            return self._parse_quoted_string(text[1:-1])

        # Check for single-quoted string
        if text.startswith("'") and text.endswith("'") and len(text) >= 2:
            return text[1:-1].replace("''", "'")

        # Remove trailing comment
        # But need to handle quoted strings
        bare_text = self._strip_comment(text)
        text = bare_text

        # Null
        if text in ('null', 'Null', 'NULL', '~', ''):
            return None

        # Boolean
        if text in ('true', 'True', 'TRUE'):
            return True
        if text in ('false', 'False', 'FALSE'):
            return False

        # Inf/NaN
        if text in ('.inf', '.Inf', '.INF'):
            return math.inf
        if text in ('-.inf', '-.Inf', '-.INF'):
            return -math.inf
        if text in ('.nan', '.NaN', '.NAN'):
            return math.nan

        # Integer
        if re.match(r'^-?(?:0|[1-9][0-9]*)$', text):
            return int(text)

        # Octal (YAML 1.1 style: 0777 or YAML 1.2 style: 0o777)
        if re.match(r'^0o[0-7]+$', text, re.IGNORECASE):
            return int(text, 8)

        # Hex
        if re.match(r'^0x[0-9a-fA-F]+$', text):
            return int(text, 16)

        # Float
        if re.match(r'^-?(?:0|[1-9][0-9]*)(?:\.[0-9]*)?(?:[eE][+-]?[0-9]+)?$', text):
            f = float(text)
            return f
        if re.match(r'^-?(?:\.[0-9]+)(?:[eE][+-]?[0-9]+)?$', text):
            return float(text)

        return text

    def _strip_comment(self, text):
        """Strip inline comment from a YAML scalar."""
        # Find # that is preceded by whitespace (not inside a quoted string)
        in_single = False
        in_double = False

        for i, c in enumerate(text):
            if c == "'" and not in_double:
                in_single = not in_single
            elif c == '"' and not in_single:
                in_double = not in_double
            elif c == '#' and not in_single and not in_double:
                if i > 0 and text[i-1] in ' \t':
                    return text[:i].rstrip()

        return text


# Sentinel value for "not yet parsed"
NOTPARSED = object()


def parse_yaml(text):
    """Parse YAML text and return Python data."""
    parser = YAMLParser(text)
    return parser.parse()


# =============================================================================
# YAML Serializer
# =============================================================================

def serialize_yaml(data, indent=0, parse_keys=False):
    """Serialize Python data to YAML string."""
    lines = []
    _yaml_dump_value(data, lines, indent, parse_keys)
    return ''.join(lines)


def _yaml_dump_value(value, lines, indent, parse_keys, inline=False):
    """Dump a value as YAML."""
    if value is None:
        lines.append('null')
    elif isinstance(value, bool):
        lines.append('true' if value else 'false')
    elif isinstance(value, int):
        lines.append(str(value))
    elif isinstance(value, float):
        lines.append(_yaml_format_float(value))
    elif isinstance(value, str):
        if not inline:
            lines.append(_yaml_quote_scalar(value))
        else:
            lines.append(_yaml_quote_scalar(value))
    elif isinstance(value, list):
        _yaml_dump_sequence(value, lines, indent, parse_keys)
    elif isinstance(value, dict):
        _yaml_dump_mapping(value, lines, indent, parse_keys)
    else:
        lines.append(str(value))


def _yaml_format_float(value):
    """Format a float for YAML output (matching Go yaml.v3 behavior)."""
    if math.isinf(value):
        return '.inf' if value > 0 else '-.inf'
    if math.isnan(value):
        return '.nan'

    # Use Go's strconv.FormatFloat behavior (shortest representation)
    # Python's repr is generally shortest
    s = repr(value)

    # Handle cases like 1e+10 format
    if 'e' in s or 'E' in s:
        # Python uses 1e+10 format, Go uses 1e+10 too
        # Normalize: remove + from exponent if it's just positive
        s = re.sub(r'e\+0*(\d)', lambda m: 'e+' + m.group(1).lstrip('0') or '0', s)
        s = re.sub(r'e-0*(\d)', lambda m: 'e-' + m.group(1).lstrip('0') or '0', s)
        return s

    return s


def _yaml_quote_scalar(value):
    """Determine the appropriate quoting for a YAML scalar string value."""
    # Empty string
    if value == '':
        return '""'

    # Check if the value contains newlines
    if '\n' in value:
        return _yaml_literal_block(value)

    # Check for tab or other control characters  
    if _has_non_printable(value):
        return _yaml_double_quote(value)

    # Check if value looks like a special YAML value that needs quoting
    if _is_yaml_special(value):
        return '"' + _escape_for_double_quote(value) + '"'

    # Check if value starts with special YAML characters
    if value[0] in '-?:,[]{}#&*!|>\'"%@`':
        return "'" + value.replace("'", "''") + "'"

    # Check if value contains ': ' or '#' or trailing space
    if ': ' in value or ':\n' in value or value.endswith(':'):
        return "'" + value.replace("'", "''") + "'"
    if ' #' in value or '\t#' in value or value.startswith('#'):
        return "'" + value.replace("'", "''") + "'"
    if value[-1] == ' ' or value[-1] == '\t':
        return "'" + value.replace("'", "''") + "'"
    if value[0] == ' ' or value[0] == '\t':
        return "'" + value.replace("'", "''") + "'"

    return value


def _has_non_printable(s):
    """Check if string has non-printable characters (other than newline)."""
    for c in s:
        if c != '\n' and (ord(c) < 0x20 or ord(c) == 0x7f):
            return True
    return False


def _yaml_literal_block(value):
    """Format a multiline string as a YAML literal block scalar."""
    # Count trailing newlines
    stripped = value.rstrip('\n')
    trailing_newlines = len(value) - len(stripped)

    if trailing_newlines == 0:
        indicator = '|-'
    elif trailing_newlines == 1:
        indicator = '|'
    else:
        indicator = '|+'

    lines = value.split('\n')
    # Remove trailing empty lines if stripped
    if indicator == '|-':
        while lines and lines[-1] == '':
            lines.pop()

    return indicator + '\n' + '\n'.join('  ' + line for line in lines)


def _yaml_double_quote(value):
    """Format a string as a YAML double-quoted scalar."""
    return '"' + _escape_for_double_quote(value) + '"'


def _escape_for_double_quote(value):
    """Escape a string for YAML double-quoting."""
    result = ''
    for c in value:
        if c == '"':
            result += '\\"'
        elif c == '\\':
            result += '\\\\'
        elif c == '\n':
            result += '\\n'
        elif c == '\r':
            result += '\\r'
        elif c == '\t':
            result += '\\t'
        elif ord(c) < 0x20:
            result += '\\x{:02x}'.format(ord(c))
        else:
            result += c
    return result


def _is_yaml_special(value):
    """Check if a value is a YAML special value that needs quoting."""
    lower = value.lower()
    # YAML 1.2 booleans and null
    if lower in ('true', 'false', 'null'):
        return True
    # YAML null variants
    if value in ('~',):
        return True
    # YAML 1.1 legacy values (yaml.v3 still quotes these to prevent ambiguity)
    if lower in ('yes', 'no', 'on', 'off'):
        return True
    # YAML numeric special values
    if lower in ('.inf', '-.inf', '.nan'):
        return True
    if lower in ('+inf', '-inf', 'inf', 'nan'):
        # These are NOT YAML specials, don't quote
        return False
    # Check for numeric values
    if _looks_like_number(value):
        return True
    return False


def _looks_like_number(value):
    """Check if a string looks like a number that would be parsed."""
    # Integer
    if re.match(r'^-?(?:0|[1-9][0-9]*)$', value):
        return True
    # Float
    if re.match(r'^-?(?:0|[1-9][0-9]*)(?:\.[0-9]*)?(?:[eE][+-]?[0-9]+)?$', value):
        return True
    # Hex
    if re.match(r'^0x[0-9a-fA-F]+$', value):
        return True
    # Octal
    if re.match(r'^0o[0-7]+$', value, re.IGNORECASE):
        return True
    return False


def _yaml_dump_sequence(seq, lines, indent, parse_keys):
    """Dump a YAML sequence."""
    if not seq:
        lines.append('[]\n')
        return

    prefix = '  ' * (indent // 2)
    for i, item in enumerate(seq):
        lines.append(prefix + '- ')
        if isinstance(item, dict) and item:
            # Inline first key-value, rest on next lines
            first = True
            for k, v in item.items():
                key_str = _yaml_dump_key(k, parse_keys)
                if first:
                    lines.append(key_str + ': ')
                    if isinstance(v, (dict, list)):
                        lines.append('\n')
                        _yaml_dump_value(v, lines, indent + 2, parse_keys)
                    else:
                        _yaml_dump_value(v, lines, indent + 2, parse_keys)
                        lines.append('\n')
                    first = False
                else:
                    lines.append(prefix + '  ' + key_str + ': ')
                    if isinstance(v, (dict, list)):
                        lines.append('\n')
                        _yaml_dump_value(v, lines, indent + 4, parse_keys)
                    else:
                        _yaml_dump_value(v, lines, indent + 2, parse_keys)
                        lines.append('\n')
        elif isinstance(item, list) and item:
            lines.append('\n')
            _yaml_dump_value(item, lines, indent + 2, parse_keys)
        else:
            _yaml_dump_value(item, lines, indent + 2, parse_keys)
            lines.append('\n')


def _yaml_dump_mapping(mapping, lines, indent, parse_keys):
    """Dump a YAML mapping."""
    if not mapping:
        lines.append('{}\n')
        return

    prefix = '  ' * (indent // 2)
    for k, v in mapping.items():
        key_str = _yaml_dump_key(k, parse_keys)
        lines.append(prefix + key_str + ': ')

        if isinstance(v, dict) and v:
            lines.append('\n')
            _yaml_dump_mapping(v, lines, indent + 2, parse_keys)
        elif isinstance(v, list) and v:
            lines.append('\n')
            _yaml_dump_sequence(v, lines, indent + 2, parse_keys)
        elif isinstance(v, str) and '\n' in v:
            # Block scalar
            block = _yaml_literal_block(v)
            lines.append(block + '\n')
        else:
            _yaml_dump_value(v, lines, indent + 2, parse_keys)
            lines.append('\n')


def _yaml_dump_key(key, parse_keys):
    """Format a key for YAML output."""
    if parse_keys:
        # Attempt to emit key as its parsed type (e.g., integer keys without quotes)
        # The key is always a string here (from JSON), but try to interpret it
        if _looks_like_integer(key):
            return key  # Output without quotes
        if _looks_like_float_key(key):
            # Convert to full float representation
            try:
                f = float(key)
                if f == int(f) and 'e' not in key.lower() and abs(f) < 1e15:
                    return str(int(f))
                else:
                    return _yaml_format_float(f)
            except ValueError:
                pass
        if key.lower() in ('true', 'false'):
            return key.lower()
        # null key -> None key in yaml... but that causes issues
        # Just don't quote it
        return key
    else:
        # Quote string keys that look like special values or numbers
        if _is_yaml_special_key(key):
            return '"' + _escape_for_double_quote(key) + '"'
        return key


def _yaml_is_safe_key(key):
    """Check if a key can be written without quotes."""
    if not key:
        return False
    # Check for characters that need quoting in keys
    if key[0] in ' \t':
        return False
    for c in key:
        if c in ':#\n{}[],':
            return False
    return True


def _yaml_is_special_key(key):
    """Check if key needs quoting."""
    return _is_yaml_special(key) or not _yaml_is_safe_key(key)


def _is_yaml_special_key(key):
    """Check if a key needs double-quoting."""
    return _is_yaml_special(key)


def _looks_like_integer(s):
