    def _parse_map_line(self, text, result, min_ind):
        """Parse a mapping line and update result dict."""
        kv = self._find_key_colon(text)
        if kv is None:
            return

        key, rest = kv

        # Check for anchor
        anchor = None
        if rest.startswith('&'):
            m = re.match(r'^&(\S+)\s*(.*)', rest)
            if m:
                anchor = m.group(1)
                rest = m.group(2).strip()

        if not rest or rest.startswith('#'):
            # Value on next lines
            self._skip_empty()
            if self.pos < len(self.lines):
                next_line = self.lines[self.pos]
                next_ind = self._indent(next_line)
                if next_ind >= min_ind:
                    value = self._parse_node(next_ind)
                else:
                    value = None
            else:
                value = None
        else:
            value = self._parse_inline_value(rest, min_ind)

        if anchor:
            self.anchors[anchor] = value

        if key == '<<':
            if isinstance(value, dict):
                for mk, mv in value.items():
                    if mk not in result:
                        result[mk] = mv
            elif isinstance(value, list):
                for item in reversed(value):
                    if isinstance(item, dict):
                        for mk, mv in item.items():
                            if mk not in result:
                                result[mk] = mv
        else:
            result[key] = value

    def _parse_flow_seq(self, text):
        result = []
        i = 0
        # Find opening [
        while i < len(text) and text[i] != '[':
            i += 1
        i += 1  # skip [

        while i < len(text):
            while i < len(text) and text[i] in ' \t\n':
                i += 1
            if i >= len(text) or text[i] == ']':
                break
            val, i = self._parse_flow_value(text, i)
            result.append(val)
            while i < len(text) and text[i] in ' \t\n':
                i += 1
            if i < len(text) and text[i] == ',':
                i += 1
        return result

    def _parse_flow_map(self, text):
        result = OrderedDict()
        i = 0
        while i < len(text) and text[i] != '{':
            i += 1
        i += 1  # skip {

        while i < len(text):
            while i < len(text) and text[i] in ' \t\n':
                i += 1
            if i >= len(text) or text[i] == '}':
                break
            key, i = self._parse_flow_value(text, i)
            while i < len(text) and text[i] in ' \t\n':
                i += 1
            if i < len(text) and text[i] == ':':
                i += 1
            while i < len(text) and text[i] in ' \t\n':
                i += 1
            if i < len(text) and text[i] not in ',}':
                val, i = self._parse_flow_value(text, i)
            else:
                val = None
            result[str(key) if key is not None else ''] = val
            while i < len(text) and text[i] in ' \t\n':
                i += 1
            if i < len(text) and text[i] == ',':
                i += 1
