    def _parse_flow_value(self, text, i):
        while i < len(text) and text[i] in ' \t':
            i += 1
        if i >= len(text):
            return None, i
        c = text[i]
        if c == '"':
            j = i + 1
            s = []
            while j < len(text) and text[j] != '"':
                if text[j] == '\\':
                    j += 1
                    if j < len(text):
                        if text[j] == 'u' and j + 4 < len(text):
                            s.append(chr(int(text[j+1:j+5], 16)))
                            j += 5
                        elif text[j] == 'U' and j + 8 < len(text):
                            s.append(chr(int(text[j+1:j+9], 16)))
                            j += 9
                        else:
                            s.append(_yaml_unescape(text[j]))
                            j += 1
                else:
                    s.append(text[j])
                    j += 1
            return ''.join(s), j + 1
        elif c == "'":
            j = i + 1
            s = []
            while j < len(text):
                if text[j] == "'" and j+1 < len(text) and text[j+1] == "'":
                    s.append("'")
                    j += 2
                elif text[j] == "'":
                    break
                else:
                    s.append(text[j])
                    j += 1
            return ''.join(s), j + 1
        elif c == '[':
            end = self._find_closing(text, i, '[', ']')
            return self._parse_flow_seq(text[i:end+1]), end + 1
        elif c == '{':
            end = self._find_closing(text, i, '{', '}')
            return self._parse_flow_map(text[i:end+1]), end + 1
        else:
            j = i
            depth = 0
            while j < len(text):
                if text[j] in '[{':
                    depth += 1
                elif text[j] in ']}':
                    if depth == 0:
                        break
                    depth -= 1
                elif text[j] == ',' and depth == 0:
                    break
                elif text[j] == '\n':
                    break
                j += 1
            scalar = text[i:j].strip()
            # Remove inline comment
            scalar = re.sub(r'\s+#.*$', '', scalar).strip()
            return self._convert_scalar(scalar), j

    def _find_closing(self, text, start, open_c, close_c):
        depth = 0
        i = start
        in_str = None
        while i < len(text):
            c = text[i]
            if in_str:
                if c == '\\' and in_str == '"':
                    i += 2
                    continue
                if c == in_str:
                    in_str = None
            elif c in '"\'':
                in_str = c
            elif c == open_c:
                depth += 1
            elif c == close_c:
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        return i - 1

    def _convert_scalar(self, text):
        if text is None:
            return None

        text = text.strip()

        # Remove inline comment  
        text = self._strip_inline_comment(text)

        if not text:
            return None

        # Double-quoted string
        if text.startswith('"') and text.endswith('"') and len(text) >= 2:
            return _yaml_unescape_str(text[1:-1])

        # Single-quoted string
        if text.startswith("'") and text.endswith("'") and len(text) >= 2:
            return text[1:-1].replace("''", "'")

        # Null
        if text in ('null', 'Null', 'NULL', '~'):
            return None

        # Boolean
        if text in ('true', 'True', 'TRUE'):
            return True
        if text in ('false', 'False', 'FALSE'):
            return False

        # Inf/NaN
        if text in ('.inf', '.Inf', '.INF'):
            return math.inf
        if text in ('-.inf', '-.Inf', '-.INF'):
            return -math.inf
        if text in ('.nan', '.NaN', '.NAN'):
            return math.nan

        # Hex integer
        if re.match(r'^0x[0-9a-fA-F_]+$', text):
            return int(text.replace('_', ''), 16)

        # Octal
        if re.match(r'^0o[0-7_]+$', text, re.IGNORECASE):
            return int(text.replace('_', ''), 8)

        # Integer
        if re.match(r'^-?(?:0|[1-9][0-9_]*)$', text):
            return int(text.replace('_', ''))

        # Float
        float_text = text.replace('_', '')
        try:
            if re.match(r'^-?(?:0|[1-9][0-9]*)(?:\.[0-9]*)?(?:[eE][+-]?[0-9]+)?$', float_text) or \
               re.match(r'^-?(?:\.[0-9]+)(?:[eE][+-]?[0-9]+)?$', float_text):
                f = float(float_text)
                return f
        except ValueError:
            pass

        return text

    def _strip_inline_comment(self, text):
        if not text:
            return text
        if text.startswith('"') or text.startswith("'"):
            return text

        # Find ' #' not inside quotes
        in_s = None
        for i, c in enumerate(text):
            if c in '"\'':
                if in_s is None:
                    in_s = c
                elif c == in_s:
                    in_s = None
            elif c == '#' and in_s is None:
                if i > 0 and text[i-1] in ' \t':
                    return text[:i].rstrip()
        return text


def parse_yaml(text):
    p = YAMLParser(text)
    return p.parse()

