class YAMLParseError(Exception):
    pass


def _yaml_unescape(c):
    mapping = {
        'n': '\n', 't': '\t', 'r': '\r', 'b': '\b', 'f': '\f',
        '"': '"', "'": "'", '\\': '\\', '/': '/', 'a': '\a',
        'v': '\v', 'e': '\x1b', '0': '\x00', ' ': ' ', '_': '\xa0',
        'N': '\x85', 'L': '\u2028', 'P': '\u2029',
    }
    return mapping.get(c, '\\' + c)


def _yaml_unescape_str(s):
    result = []
    i = 0
    while i < len(s):
        if s[i] == '\\' and i + 1 < len(s):
            nc = s[i+1]
            if nc == 'u' and i + 5 < len(s):
                result.append(chr(int(s[i+2:i+6], 16)))
                i += 6
                continue
            elif nc == 'U' and i + 9 < len(s):
                result.append(chr(int(s[i+2:i+10], 16)))
                i += 10
                continue
            elif nc == 'x' and i + 3 < len(s):
                result.append(chr(int(s[i+2:i+4], 16)))
                i += 4
                continue
            result.append(_yaml_unescape(nc))
            i += 2
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)


class YAMLParser:
    def __init__(self, text):
        # Normalize line endings
        self.text = text.replace('\r\n', '\n').replace('\r', '\n')
        self.lines = self.text.split('\n')
        self.pos = 0
        self.anchors = {}

    def parse(self):
        self._skip_doc_start()
        if self.pos >= len(self.lines):
            return None
        result = self._parse_node(0)
        return result

    def _skip_doc_start(self):
        while self.pos < len(self.lines):
            line = self.lines[self.pos]
            s = line.strip()
            if s == '---' or s == '':
                self.pos += 1
            elif s.startswith('#'):
                self.pos += 1
            else:
                break

    def _indent(self, line):
        return len(line) - len(line.lstrip(' \t'))

    def _skip_empty(self):
        while self.pos < len(self.lines):
            s = self.lines[self.pos].strip()
            if s == '' or s.startswith('#'):
                self.pos += 1
            else:
                break

    def _parse_node(self, min_indent):
        self._skip_empty()
        if self.pos >= len(self.lines):
            return None

        line = self.lines[self.pos]
        ind = self._indent(line)
        if ind < min_indent:
            return None

        stripped = line.strip()

        if stripped == '---' or stripped == '...':
            self.pos += 1
            return self._parse_node(min_indent)

        # Flow sequence
        if stripped.startswith('['):
            self.pos += 1
            return self._parse_flow_seq(stripped)

        # Flow mapping
        if stripped.startswith('{'):
            self.pos += 1
            return self._parse_flow_map(stripped)

        # Block sequence
        if re.match(r'^-(\s|$)', stripped):
            return self._parse_block_seq(ind)

        # Check for block mapping
        if self._is_mapping_line(stripped):
            return self._parse_block_map(ind)

        # Scalar
        self.pos += 1
        return self._convert_scalar(stripped)

    def _is_mapping_line(self, stripped):
        if not stripped:
            return False
        if stripped.startswith('? '):
            return True
        return self._find_key_colon(stripped) is not None

    def _find_key_colon(self, s):
        """Returns (key, rest) if s is a key: value line, else None."""
        if not s:
            return None

        if s.startswith('"'):
            # Double-quoted key
            i = 1
            while i < len(s):
                if s[i] == '\\':
                    i += 2
                    continue
                if s[i] == '"':
                    key = _yaml_unescape_str(s[1:i])
                    rest = s[i+1:].lstrip()
                    if rest.startswith(':'):
                        after = rest[1:]
                        if not after or after[0] in ' \t\n':
                            return (key, after.lstrip())
                    return None
                i += 1
            return None

        if s.startswith("'"):
            i = 1
            while i < len(s):
                if s[i] == "'" and i + 1 < len(s) and s[i+1] == "'":
                    i += 2
                    continue
                if s[i] == "'":
                    key = s[1:i].replace("''", "'")
                    rest = s[i+1:].lstrip()
                    if rest.startswith(':'):
                        after = rest[1:]
                        if not after or after[0] in ' \t\n':
                            return (key, after.lstrip())
                    return None
                i += 1
            return None

        # Unquoted key
        for i, c in enumerate(s):
            if c == ':':
                if i + 1 >= len(s) or s[i+1] in ' \t':
                    key = s[:i].rstrip()
                    rest = s[i+1:].lstrip() if i+1 < len(s) else ''
                    return (key, rest)
                if i + 1 == len(s):
                    return (s[:i].rstrip(), '')
            if c in '#\n':
                break
        return None

    def _parse_block_seq(self, ind):
        result = []
        while self.pos < len(self.lines):
            self._skip_empty()
            if self.pos >= len(self.lines):
                break
            line = self.lines[self.pos]
            cur_ind = self._indent(line)
            if cur_ind < ind:
                break
            if cur_ind > ind:
                break
            stripped = line.strip()
            if not re.match(r'^-(\s|$)', stripped):
                break

            self.pos += 1
            after_dash = stripped[1:]
            if after_dash and after_dash[0] == ' ':
                after_dash = after_dash[1:]
            elif after_dash and after_dash[0] == '\t':
                after_dash = after_dash[1:]
            else:
                after_dash = after_dash.strip()

            if not after_dash or after_dash.startswith('#'):
                # Value on next line(s)
                self._skip_empty()
                if self.pos < len(self.lines):
                    next_line = self.lines[self.pos]
                    next_ind = self._indent(next_line)
                    if next_ind > ind:
                        value = self._parse_node(next_ind)
                    else:
                        value = None
                else:
                    value = None
            else:
                # Inline value
                value = self._parse_inline_value(after_dash, ind)

            result.append(value)
        return result

    def _parse_inline_value(self, text, parent_ind):
        """Parse an inline value (after ':' or '- ')."""
        text = text.strip()

        if not text or text.startswith('#'):
            return None

        # Flow sequence
        if text.startswith('['):
            return self._parse_flow_seq(text)

        # Flow mapping
        if text.startswith('{'):
            return self._parse_flow_map(text)

        # Anchor reference
        if text.startswith('*'):
            name = text[1:].split()[0] if ' ' in text else text[1:]
            # strip trailing comments
            name = re.split(r'\s', name)[0]
            return self.anchors.get(name)

        # Anchor definition
        if text.startswith('&'):
            m = re.match(r'^&(\S+)\s*(.*)', text)
            if m:
                aname = m.group(1)
                rest = m.group(2).strip()
                if rest:
                    val = self._parse_inline_value(rest, parent_ind)
                else:
                    val = None
                self.anchors[aname] = val
                return val

        # Tag
        if text.startswith('!!'):
            m = re.match(r'^!!(\S+)\s*(.*)', text)
            if m:
                return self._parse_tagged(m.group(1), m.group(2).strip(), parent_ind)

        if text.startswith('!') and not text.startswith('!!'):
            m = re.match(r'^!(\S*)\s*(.*)', text)
            if m and m.group(1):
                return self._parse_tagged(m.group(1), m.group(2).strip(), parent_ind)

        # Block scalar
        if text.startswith('|') or text.startswith('>'):
            return self._parse_block_scalar(text, parent_ind)

        # Check if it's a mapping key
        kv = self._find_key_colon(text)
        if kv is not None:
            return self._parse_inline_map(text, parent_ind)

        # Sequence
        if re.match(r'^-(\s|$)', text):
            return self._parse_inline_seq(text, parent_ind)

        return self._convert_scalar(text)

    def _parse_inline_map(self, first_line, parent_ind):
        """Parse a mapping that starts inline and continues on next lines."""
        result = OrderedDict()

        # Parse first line
        self._parse_map_line(first_line, result, parent_ind + 1)

        # Continue with indented lines
        min_ind = parent_ind + 1
        while self.pos < len(self.lines):
            self._skip_empty()
            if self.pos >= len(self.lines):
                break
            line = self.lines[self.pos]
            cur_ind = self._indent(line)
            if cur_ind < min_ind:
                break
            stripped = line.strip()
            if re.match(r'^-(\s|$)', stripped):
                break
            kv = self._find_key_colon(stripped)
            if kv is None:
                break
            self.pos += 1
            self._parse_map_line(stripped, result, cur_ind)

        return result

    def _parse_inline_seq(self, first_line, parent_ind):
        """Parse a sequence starting inline."""
        # This case is unusual; treat as block seq from current position
        # Just go back and re-parse
        return None  # Simplified

    def _parse_tagged(self, tag, value, parent_ind):
        if tag == 'binary':
            import base64
            cleaned = re.sub(r'\s+', '', value)
            try:
                data = base64.b64decode(cleaned)
                return data.decode('latin-1')
            except Exception:
                return value
        elif tag in ('str', 'string'):
            return str(value)
        elif tag == 'int':
            try:
                return int(value, 0)
            except:
                return 0
        elif tag == 'float':
            try:
                return float(value)
            except:
                return 0.0
        elif tag == 'bool':
            return value.lower() in ('true', 'yes', 'on', '1')
        elif tag == 'null':
            return None
        return self._convert_scalar(value)

    def _parse_block_scalar(self, indicator, parent_ind):
        """Parse block scalar (| or >)."""
        style = indicator[0]
        rest = indicator[1:]

        chomp = 'clip'
        explicit_indent = None
        for c in rest.strip():
            if c == '-':
                chomp = 'strip'
            elif c == '+':
                chomp = 'keep'
            elif c.isdigit():
                explicit_indent = int(c)
            else:
                break

        content_lines = []
        base_indent = None

        while self.pos < len(self.lines):
            line = self.lines[self.pos]

            if line.strip() == '' or line.strip().startswith('#') and base_indent is None:
                # Preserve empty lines
                self.pos += 1
                content_lines.append('')
                continue

            if line.strip() == '':
                self.pos += 1
                content_lines.append('')
                continue

            cur_ind = self._indent(line)

            if base_indent is None:
                if explicit_indent is not None:
                    base_indent = parent_ind + 1 + explicit_indent - 1
                else:
                    base_indent = cur_ind

            if cur_ind < base_indent:
                break

            self.pos += 1
            content_lines.append(line[base_indent:])

        # Remove leading empty lines
        while content_lines and content_lines[0] == '':
            content_lines.pop(0)

        if style == '|':
            content = '\n'.join(content_lines)
        else:
            # Folded
            content = self._fold_scalar(content_lines)

        if chomp == 'strip':
            content = content.rstrip('\n')
        elif chomp == 'clip':
            if content:
                content = content.rstrip('\n') + '\n'
        # keep: leave as-is

        return content

    def _fold_scalar(self, lines):
        if not lines:
            return '\n'
        result = []
        i = 0
        while i < len(lines):
            line = lines[i]
            if i + 1 < len(lines):
                next_line = lines[i + 1]
                if line == '':
                    result.append('\n')
                    i += 1
                elif next_line == '':
                    result.append(line + '\n')
                    i += 1
                elif next_line.startswith(' ') or next_line.startswith('\t'):
                    result.append(line + '\n')
                    i += 1
                else:
                    result.append(line + ' ')
                    i += 1
            else:
                result.append(line)
                i += 1
        return ''.join(result) + '\n'

    def _parse_block_map(self, ind):
        result = OrderedDict()
        while self.pos < len(self.lines):
            self._skip_empty()
            if self.pos >= len(self.lines):
                break
            line = self.lines[self.pos]
            cur_ind = self._indent(line)
            if cur_ind < ind:
                break
            if cur_ind > ind:
                break
            stripped = line.strip()
            if re.match(r'^-(\s|$)', stripped):
                break

            kv = self._find_key_colon(stripped)
            if kv is None:
                break

            key, rest = kv
            self.pos += 1

            # Handle anchor in key
            # Check for anchor/alias in value
            anchor = None
            if rest.startswith('&'):
                m = re.match(r'^&(\S+)\s*(.*)', rest)
                if m:
                    anchor = m.group(1)
                    rest = m.group(2).strip()

            if not rest or rest.startswith('#'):
                # Value on next lines
                self._skip_empty()
                if self.pos < len(self.lines):
                    next_line = self.lines[self.pos]
                    next_ind = self._indent(next_line)
                    if next_ind > ind:
                        value = self._parse_node(next_ind)
                    else:
                        value = None
                else:
                    value = None
            else:
                value = self._parse_inline_value(rest, ind)

            if anchor:
                self.anchors[anchor] = value

            # Handle merge key
            if key == '<<':
                if isinstance(value, dict):
                    for mk, mv in value.items():
                        if mk not in result:
                            result[mk] = mv
                elif isinstance(value, list):
                    for item in reversed(value):
                        if isinstance(item, dict):
                            for mk, mv in item.items():
                                if mk not in result:
                                    result[mk] = mv
            else:
                result[key] = value

        return result

    def _parse_map_line(self, text, result, min_ind):
        """Parse a mapping line and update result dict."""
        kv = self._find_key_colon(text)
        if kv is None:
            return

        key, rest = kv

        # Check for anchor
        anchor = None
        if rest.startswith('&'):
            m = re.match(r'^&(\S+)\s*(.*)', rest)
            if m:
                anchor = m.group(1)
                rest = m.group(2).strip()

        if not rest or rest.startswith('#'):
            # Value on next lines
            self._skip_empty()
            if self.pos < len(self.lines):
                next_line = self.lines[self.pos]
                next_ind = self._indent(next_line)
                if next_ind >= min_ind:
                    value = self._parse_node(next_ind)
                else:
                    value = None
            else:
                value = None
        else:
            value = self._parse_inline_value(rest, min_ind)

        if anchor:
            self.anchors[anchor] = value

        if key == '<<':
            if isinstance(value, dict):
                for mk, mv in value.items():
                    if mk not in result:
                        result[mk] = mv
            elif isinstance(value, list):
                for item in reversed(value):
                    if isinstance(item, dict):
                        for mk, mv in item.items():
                            if mk not in result:
                                result[mk] = mv
        else:
            result[key] = value

    def _parse_flow_seq(self, text):
        result = []
        i = 0
        # Find opening [
        while i < len(text) and text[i] != '[':
            i += 1
        i += 1  # skip [

        while i < len(text):
            while i < len(text) and text[i] in ' \t\n':
                i += 1
            if i >= len(text) or text[i] == ']':
                break
            val, i = self._parse_flow_value(text, i)
            result.append(val)
            while i < len(text) and text[i] in ' \t\n':
                i += 1
            if i < len(text) and text[i] == ',':
                i += 1
        return result

    def _parse_flow_map(self, text):
        result = OrderedDict()
        i = 0
        while i < len(text) and text[i] != '{':
            i += 1
        i += 1  # skip {

        while i < len(text):
            while i < len(text) and text[i] in ' \t\n':
                i += 1
            if i >= len(text) or text[i] == '}':
                break
            key, i = self._parse_flow_value(text, i)
            while i < len(text) and text[i] in ' \t\n':
                i += 1
            if i < len(text) and text[i] == ':':
                i += 1
            while i < len(text) and text[i] in ' \t\n':
                i += 1
            if i < len(text) and text[i] not in ',}':
                val, i = self._parse_flow_value(text, i)
            else:
                val = None
            result[str(key) if key is not None else ''] = val
            while i < len(text) and text[i] in ' \t\n':
                i += 1
            if i < len(text) and text[i] == ',':
                i += 1
        return result

    def _parse_flow_value(self, text, i):
        while i < len(text) and text[i] in ' \t':
            i += 1
        if i >= len(text):
            return None, i
        c = text[i]
        if c == '"':
            j = i + 1
            s = []
            while j < len(text) and text[j] != '"':
                if text[j] == '\\':
                    j += 1
                    if j < len(text):
                        if text[j] == 'u' and j + 4 < len(text):
                            s.append(chr(int(text[j+1:j+5], 16)))
                            j += 5
                        elif text[j] == 'U' and j + 8 < len(text):
                            s.append(chr(int(text[j+1:j+9], 16)))
                            j += 9
                        else:
                            s.append(_yaml_unescape(text[j]))
                            j += 1
                else:
                    s.append(text[j])
                    j += 1
            return ''.join(s), j + 1
        elif c == "'":
            j = i + 1
            s = []
            while j < len(text):
                if text[j] == "'" and j+1 < len(text) and text[j+1] == "'":
                    s.append("'")
                    j += 2
                elif text[j] == "'":
                    break
                else:
                    s.append(text[j])
                    j += 1
            return ''.join(s), j + 1
        elif c == '[':
            end = self._find_closing(text, i, '[', ']')
            return self._parse_flow_seq(text[i:end+1]), end + 1
        elif c == '{':
            end = self._find_closing(text, i, '{', '}')
            return self._parse_flow_map(text[i:end+1]), end + 1
        else:
            j = i
            depth = 0
            while j < len(text):
                if text[j] in '[{':
                    depth += 1
                elif text[j] in ']}':
                    if depth == 0:
                        break
                    depth -= 1
                elif text[j] == ',' and depth == 0:
                    break
                elif text[j] == '\n':
                    break
                j += 1
            scalar = text[i:j].strip()
            # Remove inline comment
            scalar = re.sub(r'\s+#.*$', '', scalar).strip()
            return self._convert_scalar(scalar), j

    def _find_closing(self, text, start, open_c, close_c):
        depth = 0
        i = start
        in_str = None
        while i < len(text):
            c = text[i]
            if in_str:
                if c == '\\' and in_str == '"':
                    i += 2
                    continue
                if c == in_str:
                    in_str = None
            elif c in '"\'':
                in_str = c
            elif c == open_c:
                depth += 1
            elif c == close_c:
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        return i - 1

    def _convert_scalar(self, text):
        if text is None:
            return None

        text = text.strip()

        # Remove inline comment  
        text = self._strip_inline_comment(text)

        if not text:
            return None

        # Double-quoted string
        if text.startswith('"') and text.endswith('"') and len(text) >= 2:
            return _yaml_unescape_str(text[1:-1])

        # Single-quoted string
        if text.startswith("'") and text.endswith("'") and len(text) >= 2:
            return text[1:-1].replace("''", "'")

        # Null
        if text in ('null', 'Null', 'NULL', '~'):
            return None

        # Boolean
        if text in ('true', 'True', 'TRUE'):
            return True
        if text in ('false', 'False', 'FALSE'):
            return False

        # Inf/NaN
        if text in ('.inf', '.Inf', '.INF'):
            return math.inf
        if text in ('-.inf', '-.Inf', '-.INF'):
            return -math.inf
        if text in ('.nan', '.NaN', '.NAN'):
            return math.nan

        # Hex integer
        if re.match(r'^0x[0-9a-fA-F_]+$', text):
            return int(text.replace('_', ''), 16)

        # Octal
        if re.match(r'^0o[0-7_]+$', text, re.IGNORECASE):
            return int(text.replace('_', ''), 8)

        # Integer
        if re.match(r'^-?(?:0|[1-9][0-9_]*)$', text):
            return int(text.replace('_', ''))

        # Float
        float_text = text.replace('_', '')
        try:
            if re.match(r'^-?(?:0|[1-9][0-9]*)(?:\.[0-9]*)?(?:[eE][+-]?[0-9]+)?$', float_text) or \
               re.match(r'^-?(?:\.[0-9]+)(?:[eE][+-]?[0-9]+)?$', float_text):
                f = float(float_text)
                return f
        except ValueError:
            pass

        return text

    def _strip_inline_comment(self, text):
        if not text:
            return text
        if text.startswith('"') or text.startswith("'"):
            return text

        # Find ' #' not inside quotes
        in_s = None
        for i, c in enumerate(text):
            if c in '"\'':
                if in_s is None:
                    in_s = c
                elif c == in_s:
                    in_s = None
            elif c == '#' and in_s is None:
                if i > 0 and text[i-1] in ' \t':
                    return text[:i].rstrip()
        return text


def parse_yaml(text):
    p = YAMLParser(text)
    return p.parse()

