def go_format_float_yaml(f):
    """Format float for YAML output (matching Go yaml.v3 behavior)."""
    if math.isinf(f):
        return '.inf' if f > 0 else '-.inf'
    if math.isnan(f):
        return '.nan'

    r = repr(f)

    if 'e' in r:
        m, e = r.split('e')
        exp_val = int(e)
        return '{0}e+{1:02d}'.format(m, exp_val) if exp_val >= 0 else '{0}e-{1:02d}'.format(m, abs(exp_val))

    if '.' in r:
        neg = r.startswith('-')
        abs_r = r[1:] if neg else r
        int_p, dec_p = abs_r.split('.')

        if int_p == '0':
            leading_z = len(dec_p) - len(dec_p.lstrip('0'))
            exp = -(leading_z + 1)
        else:
            exp = len(int_p) - 1

        if exp < -4 or exp >= 6:
            all_digits = (int_p.lstrip('0') or '0') + dec_p
            all_digits = all_digits.rstrip('0') or '0'
            mantissa = all_digits[0]
            if len(all_digits) > 1:
                mantissa += '.' + all_digits[1:]
            result = '{0}e+{1:02d}'.format(mantissa, exp) if exp >= 0 else '{0}e-{1:02d}'.format(mantissa, abs(exp))
            return ('-' if neg else '') + result
        else:
            return r

    return r


def go_format_float_toml(f):
    """Format float for TOML output (always decimal, no scientific notation)."""
    if math.isinf(f):
        return '+inf' if f > 0 else '-inf'
    if math.isnan(f):
        return 'nan'

    r = repr(f)

    if 'e' in r:
        # Convert scientific to decimal
        m, e = r.split('e')
        exp_val = int(e)

        if '.' in m:
            int_p, dec_p = m.split('.')
        else:
            int_p = m
            dec_p = ''

        neg = int_p.startswith('-')
        abs_int_p = int_p.lstrip('-')
        all_digits = abs_int_p + dec_p

        if exp_val >= 0:
            if exp_val >= len(dec_p):
                result = all_digits + '0' * (exp_val - len(dec_p)) + '.0'
            else:
                split_pos = len(abs_int_p) + exp_val
                result = all_digits[:split_pos] + '.' + all_digits[split_pos:]
        else:
            n_left = abs(exp_val)
            result = '0.' + '0' * (n_left - 1) + all_digits

        return ('-' if neg else '') + result

    if '.' not in r:
        return r + '.0'

    return r


