        return text

    def _strip_inline_comment(self, text):
        if not text:
            return text
        if text.startswith('"') or text.startswith("'"):
            return text

        # Find ' #' not inside quotes
        in_s = None
        for i, c in enumerate(text):
            if c in '"\'':
                if in_s is None:
                    in_s = c
                elif c == in_s:
                    in_s = None
            elif c == '#' and in_s is None:
                if i > 0 and text[i-1] in ' \t':
                    return text[:i].rstrip()
