# =============================================================================

def _yaml_needs_double_quote(s):
    """Returns True if s needs double quoting (has control chars or is special)."""
    lower = s.lower()
    # YAML special values
    if lower in ('null', 'true', 'false', '~', ''):
        return True
    # YAML 1.1 legacy - yaml.v3 quotes these too
    if lower in ('yes', 'no', 'on', 'off'):
        return True
    # YAML inf/nan special values
    if lower in ('.inf', '-.inf', '.nan', '+.inf'):
        return True
    # Numbers
    if re.match(r'^-?(?:0|[1-9][0-9]*)$', s):
        return True
    if re.match(r'^-?(?:0|[1-9][0-9]*)(?:\.[0-9]*)?(?:[eE][+-]?[0-9]+)?$', s) and ('.' in s or 'e' in s.lower()):
        return True
    if re.match(r'^-?(?:\.[0-9]+)(?:[eE][+-]?[0-9]+)?$', s):
        return True
    # Hex/octal
    if re.match(r'^0x[0-9a-fA-F]+$', s):
        return True
    if re.match(r'^0o[0-7]+$', s, re.IGNORECASE):
        return True
    # Date-like
    if re.match(r'^\d{4}-\d{2}-\d{2}', s):
        return True
    return False


def _yaml_needs_single_quote(s):
    """Returns True if s needs single quoting."""
    if not s:
        return False
    if s[0] in '-?:,[]{}#&*!|>\'"@`%':
        return True
    if s[-1] in ' \t':
        return True
    if s[0] in ' \t':
        return True
    if ': ' in s or ':\t' in s or s.endswith(':'):
        return True
    if ' #' in s or '\t#' in s:
        return True
    return False


def _yaml_has_control(s):
    for c in s:
        if c != '\n' and (ord(c) < 0x20 or ord(c) == 0x7f):
            return True
    return False


def yaml_quote_scalar(s):
    """Return properly quoted YAML scalar."""
    if s == '':
        return '""'

    if '\n' in s:
        return _yaml_literal_block(s)

    if _yaml_has_control(s):
        return '"' + _yaml_escape_dq(s) + '"'

    if _yaml_needs_double_quote(s):
        return '"' + _yaml_escape_dq(s) + '"'

    if _yaml_needs_single_quote(s):
        return "'" + s.replace("'", "''") + "'"

    return s


def _yaml_escape_dq(s):
    result = []
    for c in s:
        if c == '"':
            result.append('\\"')
        elif c == '\\':
            result.append('\\\\')
        elif c == '\n':
            result.append('\\n')
        elif c == '\r':
            result.append('\\r')
        elif c == '\t':
            result.append('\\t')
        elif ord(c) < 0x20:
            result.append('\\x{:02x}'.format(ord(c)))
        else:
            result.append(c)
    return ''.join(result)


def _yaml_literal_block(s):
    stripped = s.rstrip('\n')
    n_trail = len(s) - len(stripped)

    if n_trail == 0:
        indicator = '|-'
    elif n_trail == 1:
        indicator = '|'
    else:
        indicator = '|+'

    lines = s.split('\n')
    if indicator == '|-':
        while lines and lines[-1] == '':
            lines.pop()

    return indicator + '\n' + '\n'.join('  ' + l for l in lines)


def _yaml_key_str(key, parse_keys):
    """Format a key for YAML output."""
    if parse_keys:
        # Try to parse as integer
        if re.match(r'^-?(?:0|[1-9][0-9]*)$', key):
            return key
        # Try as float
        try:
            f = float(key)
            # Format as Go would
            r = repr(f)
            if 'e' in r:
                m, e = r.split('e')
                exp_val = int(e)
                return '{0}e+{1:02d}'.format(m, exp_val) if exp_val >= 0 else '{0}e-{1:02d}'.format(m, abs(exp_val))
            # Check if it's integer-valued
