import datetime


def serialize_toml(data, indent=False):
    out = []
    _toml_write_table(data, out, '', indent, False)
    return ''.join(out)


def _toml_escape_str(s):
    result = []
    for c in s:
        if c == '"':
            result.append('\\"')
        elif c == '\\':
            result.append('\\\\')
        elif c == '\n':
            result.append('\\n')
        elif c == '\r':
            result.append('\\r')
        elif c == '\t':
            result.append('\\t')
        elif ord(c) < 0x20:
            result.append('\\u{:04x}'.format(ord(c)))
        else:
            result.append(c)
    return ''.join(result)


def _toml_format_value(v):
    """Format a scalar TOML value."""
    if v is None:
        return None  # TOML can't represent null
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return go_format_float_toml(v)
    if isinstance(v, str):
        return '"' + _toml_escape_str(v) + '"'
    if isinstance(v, datetime.datetime):
        return _toml_format_datetime(v)
    if isinstance(v, datetime.date):
        # date-only: convert to datetime at midnight UTC
        dt = datetime.datetime(v.year, v.month, v.day, tzinfo=datetime.timezone.utc)
        return _toml_format_datetime(dt)
    if isinstance(v, datetime.time):
        # time-only: use 0000-01-01
        dt = datetime.datetime(1, 1, 1, v.hour, v.minute, v.second, v.microsecond)
        if v.tzinfo:
            dt = dt.replace(tzinfo=v.tzinfo)
        else:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return _toml_format_datetime(dt)
    return None


def _toml_format_datetime(dt):
    """Format datetime for TOML/JSON output."""
    if dt.tzinfo is not None:
        # Has timezone
        offset = dt.utcoffset()
        if offset == datetime.timedelta(0):
            # UTC
            s = dt.strftime('%Y-%m-%dT%H:%M:%S')
            if dt.microsecond:
                s += '.{:06d}'.format(dt.microsecond).rstrip('0')
            return s + 'Z'
        else:
            # Offset timezone
            s = dt.strftime('%Y-%m-%dT%H:%M:%S')
            if dt.microsecond:
                s += '.{:06d}'.format(dt.microsecond).rstrip('0')
            total_seconds = int(offset.total_seconds())
            sign = '+' if total_seconds >= 0 else '-'
            total_seconds = abs(total_seconds)
            h, m = divmod(total_seconds // 60, 60)
            return s + '{}{:02d}:{:02d}'.format(sign, h, m)
    else:
        # No timezone - local datetime
        s = dt.strftime('%Y-%m-%dT%H:%M:%S')
        if dt.microsecond:
            s += '.{:06d}'.format(dt.microsecond).rstrip('0')
        return s


def _is_all_scalars(lst):
    """Check if list contains only scalar values."""
    for item in lst:
        if isinstance(item, (dict, list)):
            return False
    return True


def _has_table_values(d):
    """Check if dict has any table/array values."""
    for v in d.values():
        if isinstance(v, dict):
            return True
        if isinstance(v, list) and v and isinstance(v[0], dict):
            return True
    return False


def _toml_write_inline_array(lst, out):
    """Write array inline."""
    out.append('[')
    parts = []
    for item in lst:
        if isinstance(item, list):
            sub = []
            _toml_write_inline_array(item, sub)
            parts.append(''.join(sub))
        elif isinstance(item, dict):
            # Inline table
            sub = []
            _toml_write_inline_table(item, sub)
            parts.append(''.join(sub))
        else:
            fv = _toml_format_value(item)
            if fv is not None:
                parts.append(fv)
    out.append(', '.join(parts))
    out.append(']')


def _toml_write_inline_table(d, out):
    out.append('{')
    parts = []
    for k, v in d.items():
        fv = _toml_format_value(v)
        if fv is not None:
            parts.append(k + ' = ' + fv)
    out.append(', '.join(parts))
    out.append('}')


def _toml_write_table(data, out, prefix, indent_flag, is_array_item):
    """Write a TOML table."""
    if not isinstance(data, dict):
        return

    ind = '  ' if indent_flag else ''

    # First, write scalar and inline-array values
    deferred = []  # (key, value) for sub-tables
    arr_tables = []  # (key, value) for array of tables

    for k, v in data.items():
        if v is None:
            # Skip null values in TOML
            continue
        if isinstance(v, dict):
            deferred.append((k, v))
        elif isinstance(v, list) and v and isinstance(v[0], dict):
            arr_tables.append((k, v))
        elif isinstance(v, list) and v and any(isinstance(x, dict) for x in v):
            arr_tables.append((k, v))
        elif isinstance(v, list):
            # Inline array
            arr_out = []
            _toml_write_inline_array(v, arr_out)
            key_str = k
            out.append(ind + key_str + ' = ' + ''.join(arr_out) + '\n')
        else:
            fv = _toml_format_value(v)
            if fv is not None:
                out.append(ind + k + ' = ' + fv + '\n')

    # Write sub-tables
    for k, v in deferred:
        table_key = (prefix + '.' + k) if prefix else k
        out.append('\n')
        out.append(ind + '[' + table_key + ']\n')
        _toml_write_table(v, out, table_key, indent_flag, False)

    # Write array of tables
    for k, v in arr_tables:
        table_key = (prefix + '.' + k) if prefix else k
        for item in v:
            out.append('\n')
            out.append(ind + '[[' + table_key + ']]\n')
            if isinstance(item, dict):
                _toml_write_table(item, out, table_key, indent_flag, True)
            else:
                fv = _toml_format_value(item)
                if fv is not None:
                    out.append(ind + 'value = ' + fv + '\n')


# =============================================================================
# JSON handling
# =============================================================================

def parse_json(text):
    """Parse JSON preserving order."""
    decoder = json.JSONDecoder(object_pairs_hook=OrderedDict)
    return decoder.decode(text)


def serialize_json(data, escape_html=False, indent_flag=False, no_inf_nan=False):
    """Serialize to JSON."""
    # Convert data with inf/nan handling
    converted = _json_convert(data, escape_html, no_inf_nan)

    if indent_flag:
        result = json.dumps(converted, indent=2, ensure_ascii=False)
    else:
        result = json.dumps(converted, separators=(',', ':'), ensure_ascii=False)

    if escape_html:
        result = result.replace('&', '\\u0026').replace('<', '\\u003c').replace('>', '\\u003e')

    return result + '\n'


def _json_convert(data, escape_html, no_inf_nan):
    if isinstance(data, float):
        if math.isinf(data) or math.isnan(data):
            if no_inf_nan:
                if math.isnan(data):
                    return None
                return MAX_FLOAT if data > 0 else MIN_FLOAT
            else:
                if math.isnan(data):
                    return 'NaN'
                return 'Infinity' if data > 0 else '-Infinity'
        return data
    if isinstance(data, dict):
        return OrderedDict((k, _json_convert(v, escape_html, no_inf_nan)) for k, v in data.items())
    if isinstance(data, list):
        return [_json_convert(item, escape_html, no_inf_nan) for item in data]
    if isinstance(data, datetime.datetime):
        return _toml_format_datetime(data) + 'Z' if data.tzinfo is None else _toml_format_datetime(data)
    if isinstance(data, datetime.date):
        dt = datetime.datetime(data.year, data.month, data.day, tzinfo=datetime.timezone.utc)
        return _toml_format_datetime(dt)
    if isinstance(data, datetime.time):
        dt = datetime.datetime(1, 1, 1, data.hour, data.minute, data.second, data.microsecond)
        if data.tzinfo:
            dt = dt.replace(tzinfo=data.tzinfo)
        else:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return _toml_format_datetime(dt)
    return data

