# =============================================================================
# HCL Parser
# =============================================================================

class HCLParseError(Exception):
    pass


class HCLParser:
    """Parse HCL v1 format."""

    def __init__(self, text):
        self.text = text
        self.pos = 0

    def parse(self):
        result = OrderedDict()
        self._parse_body(result, top=True)
        return result

    def _skip_ws(self):
        while self.pos < len(self.text) and self.text[self.pos] in ' \t\r\n':
            self.pos += 1

    def _skip_ws_line(self):
        """Skip whitespace but not newlines."""
        while self.pos < len(self.text) and self.text[self.pos] in ' \t':
            self.pos += 1

    def _skip_comment(self):
        """Skip comment if at comment start."""
        if self.pos >= len(self.text):
            return False
        c = self.text[self.pos]
        if c == '#':
            while self.pos < len(self.text) and self.text[self.pos] != '\n':
                self.pos += 1
            return True
        if c == '/' and self.pos + 1 < len(self.text):
            if self.text[self.pos + 1] == '/':
                while self.pos < len(self.text) and self.text[self.pos] != '\n':
                    self.pos += 1
                return True
            if self.text[self.pos + 1] == '*':
                self.pos += 2
                while self.pos < len(self.text) - 1:
                    if self.text[self.pos] == '*' and self.text[self.pos + 1] == '/':
                        self.pos += 2
                        return True
                    self.pos += 1
                return True
        return False

    def _skip_ws_and_comments(self):
        while self.pos < len(self.text):
            if self.text[self.pos] in ' \t\r\n':
                self.pos += 1
            elif self._skip_comment():
                pass
            else:
                break

    def _peek(self):
        if self.pos >= len(self.text):
            return None
        return self.text[self.pos]

    def _read_ident(self):
        start = self.pos
        while self.pos < len(self.text) and (self.text[self.pos].isalnum() or self.text[self.pos] in '_-.'):
            self.pos += 1
        return self.text[start:self.pos]

    def _read_quoted_string(self):
        """Read a double-quoted string."""
        if self.pos >= len(self.text) or self.text[self.pos] != '"':
            raise HCLParseError("Expected '\"'")
        self.pos += 1
        result = []
        while self.pos < len(self.text) and self.text[self.pos] != '"':
            c = self.text[self.pos]
            if c == '\\':
                self.pos += 1
                if self.pos < len(self.text):
                    nc = self.text[self.pos]
                    if nc == 'n':
                        result.append('\n')
                    elif nc == 't':
                        result.append('\t')
                    elif nc == 'r':
                        result.append('\r')
                    elif nc == '"':
                        result.append('"')
                    elif nc == '\\':
                        result.append('\\')
                    elif nc == '/':
                        result.append('/')
                    elif nc == 'b':
                        result.append('\b')
                    elif nc == 'f':
                        result.append('\f')
                    elif nc == 'u' and self.pos + 4 < len(self.text):
                        result.append(chr(int(self.text[self.pos+1:self.pos+5], 16)))
                        self.pos += 4
                    else:
                        result.append('\\')
                        result.append(nc)
                    self.pos += 1
            else:
                result.append(c)
                self.pos += 1
        if self.pos < len(self.text):
            self.pos += 1  # skip closing "
        return ''.join(result)

    def _read_heredoc(self):
        """Read a heredoc string <<EOF ... EOF"""
        # Already past <<
        # Read the marker
        marker_start = self.pos
        while self.pos < len(self.text) and self.text[self.pos] not in '\n\r':
            self.pos += 1
        marker = self.text[marker_start:self.pos].strip()
        # Skip newline
        if self.pos < len(self.text) and self.text[self.pos] == '\n':
            self.pos += 1
        # Read until marker
        result = []
        while self.pos < len(self.text):
            line_start = self.pos
            while self.pos < len(self.text) and self.text[self.pos] not in '\n\r':
                self.pos += 1
            line = self.text[line_start:self.pos]
            if line.strip() == marker:
                if self.pos < len(self.text) and self.text[self.pos] in '\n\r':
                    self.pos += 1
                break
            result.append(line)
            if self.pos < len(self.text) and self.text[self.pos] in '\n\r':
                result.append('\n')
                self.pos += 1
        return ''.join(result)

    def _read_value(self):
        """Read an HCL value."""
        self._skip_ws()
        if self.pos >= len(self.text):
            return None

        c = self.text[self.pos]

        if c == '"':
            return self._read_quoted_string()

        if c == '[':
            return self._read_array()

        if c == '{':
            obj = OrderedDict()
            self.pos += 1
            self._parse_body(obj)
            return obj

        if c == '<' and self.pos + 1 < len(self.text) and self.text[self.pos+1] == '<':
            self.pos += 2
            return self._read_heredoc()

        # Number or identifier
        start = self.pos
        # Read until whitespace, comma, newline, }
        while self.pos < len(self.text) and self.text[self.pos] not in ' \t\r\n,}]#/':
            self.pos += 1
        token = self.text[start:self.pos]

        if not token:
            return None

        # Try to parse as number or bool/null
        if token.lower() == 'true':
            return True
        if token.lower() == 'false':
            return False
        if token.lower() in ('null', 'nil'):
            return None

        # Try integer
        try:
            return int(token)
        except ValueError:
            pass

        # Try float
        try:
            return float(token)
        except ValueError:
            pass

        return token

    def _read_array(self):
        """Read an HCL array."""
        if self.text[self.pos] != '[':
            raise HCLParseError("Expected '['")
        self.pos += 1
        result = []

        while True:
            self._skip_ws_and_comments()
            if self.pos >= len(self.text) or self.text[self.pos] == ']':
                break
            val = self._read_value()
            result.append(val)
            self._skip_ws_and_comments()
            if self.pos < len(self.text) and self.text[self.pos] == ',':
                self.pos += 1

        if self.pos < len(self.text) and self.text[self.pos] == ']':
            self.pos += 1

        return result

    def _parse_body(self, result, top=False):
        """Parse a body of key=value or block statements."""
        while True:
            self._skip_ws_and_comments()
            if self.pos >= len(self.text):
                break

            c = self.text[self.pos]

            if c == '}':
                if not top:
                    self.pos += 1
                break

            # Read key
            if c == '"':
                key = self._read_quoted_string()
            elif c.isalpha() or c in '_':
                key = self._read_ident()
            else:
                # Error or end
                if top:
                    # Get context for error message
                    line_start = self.text.rfind('\n', 0, self.pos) + 1
                    line_end = self.text.find('\n', self.pos)
                    if line_end == -1:
                        line_end = len(self.text)
                    line_content = self.text[line_start:line_end]
                    line_num = self.text[:self.pos].count('\n') + 2
                    raise HCLParseError("At {0}:1: key '{1}' expected start of object ('{{') or assignment ('=')".format(line_num, line_content))
                break

            self._skip_ws()

            if self.pos >= len(self.text):
                break

            c = self.text[self.pos]

            # Check for block labels (multiple keys before {)
            if c == '"' or (c.isalpha() or c == '_'):
                # Block with labels
                labels = [key]
                while self.pos < len(self.text):
                    self._skip_ws()
                    if self.pos >= len(self.text):
                        break
                    c2 = self.text[self.pos]
                    if c2 == '{':
                        break
                    if c2 == '=':
                        break
                    if c2 == '"':
                        labels.append(self._read_quoted_string())
                    elif c2.isalpha() or c2 == '_':
                        labels.append(self._read_ident())
                    else:
                        break

                self._skip_ws()
                if self.pos < len(self.text) and self.text[self.pos] == '{':
                    # Block
                    self.pos += 1
                    block_body = OrderedDict()
                    self._parse_body(block_body)

                    # Build nested structure: labels[0][labels[1]]...[body]
                    # In HCL, blocks create arrays
                    obj = block_body
                    for label in reversed(labels[1:]):
                        obj = OrderedDict([(label, [obj])])

                    outer_key = labels[0]
                    if outer_key in result:
                        existing = result[outer_key]
                        if isinstance(existing, list):
                            existing.append(obj)
                        else:
                            result[outer_key] = [existing, obj]
                    else:
                        result[outer_key] = [obj]
                    continue
                elif self.pos < len(self.text) and self.text[self.pos] == '=':
                    # It was just label = value
                    key = labels[0] if len(labels) == 1 else labels[-1]
                    # Actually reset - the first ident IS the key
                    # and the rest are extra junk
                    pass

            if self.pos < len(self.text) and self.text[self.pos] == '=':
                self.pos += 1
                self._skip_ws()
                value = self._read_value()
                result[key] = value
                # Skip optional newline/semicolon
                self._skip_ws_line()
                if self.pos < len(self.text) and self.text[self.pos] in '\n\r;':
                    self.pos += 1
            else:
                # Unexpected token
                break


def parse_hcl(text):
    p = HCLParser(text)
    try:
        return p.parse()
    except HCLParseError:
        raise
    except Exception as e:
        raise HCLParseError(str(e))

