# =============================================================================
# HCL Serializer
# =============================================================================

def _hcl_escape_str(s):
    result = []
    for c in s:
        if c == '"':
            result.append('\\"')
        elif c == '\\':
            result.append('\\\\')
        elif c == '\n':
            result.append('\\n')
        elif c == '\r':
            result.append('\\r')
        elif c == '\t':
            result.append('\\t')
        elif ord(c) < 0x20:
            result.append('\\u{:04x}'.format(ord(c)))
        else:
            result.append(c)
    return ''.join(result)


def _hcl_format_value(v, indent_str, no_inf_nan):
    """Format a value for HCL output."""
    if v is None:
        return ''  # HCL null is just empty
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        if math.isinf(v) or math.isnan(v):
            if no_inf_nan:
                if math.isnan(v):
                    return ''  # null
                return repr(MAX_FLOAT if v > 0 else MIN_FLOAT)
            else:
                if math.isnan(v):
                    return '"NaN"'
                return '"Infinity"' if v > 0 else '"-Infinity"'
        return go_format_float_yaml(v)  # Use same format as YAML
    if isinstance(v, str):
        return '"' + _hcl_escape_str(v) + '"'
    if isinstance(v, list):
        return _hcl_format_array(v, indent_str, no_inf_nan)
    if isinstance(v, dict):
        return _hcl_format_object(v, indent_str, no_inf_nan)
    if isinstance(v, (datetime.datetime, datetime.date, datetime.time)):
        s = _json_convert(v, False, False)
        if isinstance(s, str):
            return '"' + s + '"'
    return str(v)


def _hcl_format_array(lst, indent_str, no_inf_nan):
    """Format an array for HCL."""
    if not lst:
        return '[]'

    # Check if it's array of objects -> repeated blocks
    if all(isinstance(x, dict) for x in lst):
        return None  # Will be handled as repeated key

    parts = []
    for item in lst:
        if isinstance(item, list):
            parts.append(_hcl_format_array(item, indent_str, no_inf_nan))
        elif isinstance(item, dict):
            parts.append(_hcl_format_object(item, indent_str, no_inf_nan))
        else:
            parts.append(_hcl_format_value(item, indent_str, no_inf_nan))

    return '[' + ', '.join(parts) + ']'


def _hcl_format_object(d, indent_str, no_inf_nan):
    """Format a dict as an HCL object."""
    out = []
    out.append('{\n')
    for k, v in d.items():
        fv = _hcl_format_value(v, indent_str + '  ', no_inf_nan)
        out.append(indent_str + '  ' + '"' + k + '" = ' + str(fv) + '\n\n')
    out.append(indent_str + '}')
    return ''.join(out)


def serialize_hcl(data, no_inf_nan=False):
    """Serialize data to HCL format."""
    if not isinstance(data, dict):
        return ''

    out = []
    _hcl_write_body(data, out, '', no_inf_nan)
    return ''.join(out)


def _hcl_write_body(data, out, indent, no_inf_nan):
    """Write HCL body."""
    first = True
    for k, v in data.items():
        if not first:
            out.append('\n')
        first = False

        if isinstance(v, list) and v and all(isinstance(x, dict) for x in v):
            # Array of objects -> repeated blocks
            for item in v:
                if not first:
                    out.append('\n')
                out.append(indent + '"' + k + '" = {\n')
                _hcl_write_body(item, out, indent + '  ', no_inf_nan)
                out.append(indent + '}')
                first = False
        elif isinstance(v, dict):
            # Check if it looks like a block hierarchy
            out.append(indent + '"' + k + '" = {\n')
            _hcl_write_body(v, out, indent + '  ', no_inf_nan)
            out.append(indent + '}')
        else:
            fv = _hcl_format_value(v, indent, no_inf_nan)
            if fv is None:
                fv = ''
            out.append(indent + '"' + k + '" = ' + fv)

