    invalid_flags = []

    for arg in args:
        if arg.startswith('-'):
            flags = arg[1:]
            for c in flags:
                if c not in VALID_FLAGS:
                    invalid_flags.append(c)
                else:
                    flag_chars.add(c)
        else:
