                    conversion = 'jy'
                elif c == 'y':
                    conversion = 'yj'
                elif c == 't':
                    conversion = 'tj'
                elif c == 'c':
                    conversion = 'cj'
                else:
                    invalid_flags.extend(conv_chars)
            else:
                # Invalid combination
                for c in conv_chars:
                    if c not in 'ytjcr':
                        invalid_flags.append(c)
                # Check if combination is valid
                if conv_key not in CONVERSIONS:
                    invalid_flags.extend(conv_chars)

    if invalid_flags:
        sys.stderr.write(USAGE.format(prog=prog))
        sys.stderr.write('\n')
        # Report unique invalid flags (not conversion format chars that were already handled)
        all_input_chars = []
        for arg in args:
            if arg.startswith('-'):
                all_input_chars.extend(arg[1:])
        bad = []
        seen = set()
        for c in all_input_chars:
            if c not in VALID_FLAGS and c not in seen:
                seen.add(c)
                bad.append(c)
        if bad:
            sys.stderr.write('Error: invalid flags specified: ' + ' '.join(bad) + '\n')
        sys.exit(1)

    src_fmt, dst_fmt = CONVERSIONS[conversion]

    # Read stdin
    try:
        text = sys.stdin.read()
    except KeyboardInterrupt:
        sys.exit(1)

    # Parse
    try:
        if src_fmt == 'yaml':
            data = parse_yaml(text)
        elif src_fmt == 'toml':
            data = parse_toml(text)
        elif src_fmt == 'json':
            data = parse_json(text)
        elif src_fmt == 'hcl':
            data = parse_hcl(text)
    except Exception as e:
        fmt_name = {'yaml': 'YAML', 'toml': 'TOML', 'json': 'JSON', 'hcl': 'HCL'}[src_fmt]
        sys.stderr.write('Error parsing {0}: {1}\n'.format(fmt_name, str(e)))
        sys.exit(1)

    # Convert inf/nan strings from source
    if src_fmt in ('json', 'hcl') and dst_fmt in ('yaml', 'toml', 'hcl') and not no_inf_nan:
        data = _convert_inf_nan_strings(data, False)

    # Convert TOML datetime objects if needed
    if src_fmt == 'toml':
        if dst_fmt in ('yaml', 'json', 'hcl'):
            data = _toml_data_for_output(data, dst_fmt)

    # Convert YAML datetime strings if needed
    if src_fmt == 'yaml' and dst_fmt == 'toml':
        data = _yaml_data_to_toml(data)

    # Serialize
    try:
        if dst_fmt == 'json':
            output = serialize_json(data, escape_html=escape_html, 
                                     indent_flag=indent_flag, no_inf_nan=no_inf_nan)
        elif dst_fmt == 'yaml':
            output = serialize_yaml(data, indent=0, parse_keys=parse_keys)
        elif dst_fmt == 'toml':
            output = serialize_toml(data, indent=indent_flag)
        elif dst_fmt == 'hcl':
            output = serialize_hcl(data, no_inf_nan=no_inf_nan)
    except Exception as e:
        fmt_name = {'yaml': 'YAML', 'toml': 'TOML', 'json': 'JSON', 'hcl': 'HCL'}[dst_fmt]
        sys.stderr.write('Error writing {0}: {1}\n'.format(fmt_name, str(e)))
        sys.exit(1)

    sys.stdout.write(output)


