    """Convert TOML datetime objects for output format."""
    if dst_fmt == 'yaml':
        # For YAML output, pass datetime objects through - the YAML serializer handles them
        if isinstance(data, dict):
            return OrderedDict((k, _toml_data_for_output(v, dst_fmt)) for k, v in data.items())
        if isinstance(data, list):
            return [_toml_data_for_output(item, dst_fmt) for item in data]
        return data
    elif dst_fmt in ('json', 'hcl'):
        # Convert to string for JSON/HCL
        if isinstance(data, datetime.datetime):
            return _toml_format_datetime(data)
        if isinstance(data, datetime.date):
            dt = datetime.datetime(data.year, data.month, data.day, tzinfo=datetime.timezone.utc)
            return _toml_format_datetime(dt)
        if isinstance(data, datetime.time):
            dt = datetime.datetime(1, 1, 1, data.hour, data.minute, data.second, data.microsecond)
            if data.tzinfo:
                dt = dt.replace(tzinfo=data.tzinfo)
            else:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return _toml_format_datetime(dt)
        if isinstance(data, dict):
            return OrderedDict((k, _toml_data_for_output(v, dst_fmt)) for k, v in data.items())
